def transform(grid):
    """Mark background cells between two adjacent motif cells in each row."""
    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    colors = {v for row in grid for v in row if v != bg}
    motif = next(iter(colors))
    for r, row in enumerate(grid):
        for c in range(1, len(row) - 1):
            if row[c] == bg and row[c - 1] == motif and row[c + 1] == motif:
                out[r][c] = 2
    return out
